{
  "name": "opencode-reminders",
  "version": "1.0.1",
  "description": "Reminder plugin for OpenCode - schedule actions to run at intervals",
  "keywords": ["opencode", "reactive", "plugin", "reminders", "scheduler"],
  "author": "zelenkovsky",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/zelenkovsky/opencode-reminders"
  },
  "bugs": {
    "url": "https://github.com/zelenkovsky/opencode-reminders/issues"
  },
  "homepage": "https://github.com/zelenkovsky/opencode-reminders#readme",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "types.ts",
    "storage.ts",
    "scheduler.ts",
    "logger.ts",
    "tools/",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "test:types": "bun test test/types.test.ts",
    "test:storage": "bun test test/storage.test.ts",
    "test:logger": "bun test test/logger.test.ts",
    "test:config": "bun test test/config.test.ts",
    "test:scheduler": "bun test test/scheduler.test.ts",
    "test:integration": "bun test test/integration.test.ts",
    "test:watch": "bun test --watch"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^0.15.7",
    "@opencode-ai/sdk": "^0.15.7",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@types/bun": "^1.3.0",
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  }
}
